func marshalPropertyValue(enc *jsontext.Encoder, value propertyValue) error {
	switch v := value.(type) {
	case pvLengthSlice:
		return marshalLengthSlice(enc, v)
	case pvNodeIDVec:
		return json.MarshalEncode(enc, []NodeID(v))
	case pvNodeID:
		return json.MarshalEncode(enc, NodeID(v))
	case pvString:
		return json.MarshalEncode(enc, string(v))
	case pvF64:
		return json.MarshalEncode(enc, float64(v))
	case pvF32:
		return json.MarshalEncode(enc, float32(v))
	case pvUsize:
		return json.MarshalEncode(enc, int(v))
	case pvColor:
		return json.MarshalEncode(enc, Color(v))
	case pvTextDecoration:
		return json.MarshalEncode(enc, TextDecoration(v))
	case pvCoordSlice:
		return json.MarshalEncode(enc, []float32(v))
	case pvBool:
		return json.MarshalEncode(enc, bool(v))
	case pvInvalid:
		return json.MarshalEncode(enc, Invalid(v))
	case pvToggled:
		return json.MarshalEncode(enc, Toggled(v))
	case pvLive:
		return json.MarshalEncode(enc, Live(v))
	case pvTextDirection:
		return json.MarshalEncode(enc, TextDirection(v))
	case pvOrientation:
		return json.MarshalEncode(enc, Orientation(v))
	case pvSortDirection:
		return json.MarshalEncode(enc, SortDirection(v))
	case pvAriaCurrent:
		return json.MarshalEncode(enc, AriaCurrent(v))
	case pvAutoComplete:
		return json.MarshalEncode(enc, AutoComplete(v))
	case pvHasPopup:
		return json.MarshalEncode(enc, HasPopup(v))
	case pvListStyle:
		return json.MarshalEncode(enc, ListStyle(v))
	case pvTextAlign:
		return json.MarshalEncode(enc, TextAlign(v))
	case pvVerticalOffset:
		return json.MarshalEncode(enc, VerticalOffset(v))
	case pvAffine:
		return json.MarshalEncode(enc, Affine(v))
	case pvRect:
		return json.MarshalEncode(enc, Rect(v))
	case pvTextSelection:
		return json.MarshalEncode(enc, TextSelection(v))
	case pvCustomActionVec:
		return json.MarshalEncode(enc, []CustomAction(v))
	case pvTreeID:
		return json.MarshalEncode(enc, TreeID(v))
	}
	return nil
}

